import{_ as r,c as i,o as n,j as a,a8 as t,t as s,a as l}from"./chunks/framework.C_eYonIk.js";const q=JSON.parse('{"title":"重来3：跳出疯狂的忙碌 - 读书笔记","description":"","frontmatter":{"title":"重来3：跳出疯狂的忙碌 - 读书笔记","outline":[2,2],"finishedDate":"2023-10-01"},"headers":[],"relativePath":"blog/read/books/重来3跳出疯狂的忙碌.md","filePath":"blog/read/books/重来3跳出疯狂的忙碌.md","lastUpdated":1795017144000}'),v={name:"blog/read/books/重来3跳出疯狂的忙碌.md"},o={class:"social-psychology-notes"},c={class:"reading-book","aria-label":"书籍信息"},p={class:"reading-book-info"},f={class:"reading-metadata"},b=["datetime"];function h(d,e,u,x,k,g){return n(),i("div",null,[a("div",o,[e[8]||(e[8]=a("header",{class:"reading-header"},[a("h1",null,"重来3：跳出疯狂的忙碌"),a("p",{class:"reading-byline"},"作者：【美】贾森·弗里德 【丹】戴维·海涅迈尔·汉森"),a("div",{class:"reading-stats"},[a("span",null,"22 条摘抄"),a("span",null,"微信读书")])],-1)),a("section",c,[e[7]||(e[7]=a("div",{class:"reading-cover"},[a("img",{src:"https://wfqqreader-1252317822.image.myqcloud.com/cover/124/32463124/t6_32463124.jpg",alt:"重来3：跳出疯狂的忙碌封面",width:"160",loading:"lazy"})],-1)),a("div",p,[e[4]||(e[4]=a("p",{class:"reading-book-title"},"书籍信息",-1)),a("dl",f,[e[1]||(e[1]=t("<div data-v-849ea9f1><dt data-v-849ea9f1>书名</dt><dd data-v-849ea9f1>重来3：跳出疯狂的忙碌</dd></div><div data-v-849ea9f1><dt data-v-849ea9f1>作者</dt><dd data-v-849ea9f1>【美】贾森·弗里德 【丹】戴维·海涅迈尔·汉森</dd></div><div data-v-849ea9f1><dt data-v-849ea9f1>出版社</dt><dd data-v-849ea9f1>电子工业出版社</dd></div><div data-v-849ea9f1><dt data-v-849ea9f1>出版时间</dt><dd data-v-849ea9f1>2020-07-01 00:00:00</dd></div>",4)),a("div",null,[e[0]||(e[0]=a("dt",null,"完读日期",-1)),a("dd",null,[a("time",{datetime:d.$frontmatter.finishedDate},s(d.$frontmatter.finishedDate),9,b)])]),e[2]||(e[2]=a("div",null,[a("dt",null,"ISBN"),a("dd",null,"9787121390616")],-1)),e[3]||(e[3]=a("div",null,[a("dt",null,"分类"),a("dd",null,"经济理财-管理")],-1))]),e[5]||(e[5]=a("a",{class:"reading-original-link",href:"https://weread.qq.com/web/reader/0ba3276071ef59140ba5a51",target:"_blank",rel:"noopener noreferrer"},[l("在微信读书中打开 "),a("span",{"aria-hidden":"true"},"↗")],-1)),e[6]||(e[6]=a("details",{class:"reading-description"},[a("summary",null,"书籍简介"),a("p",null,"妙解创业如何逃离内卷？打工人如何摆脱焦虑？慢公司如何跑赢新经济？Jason Fried和David Hans-son一直在为读者指出通向高效工作的新路。如今，他们再次带着一套大胆的策略卷土重来，告诉读者该如何创建理想的公司文化。他们的方法直击工作中的混乱、焦虑与压力，而这些如同瘟疫一般，侵扰着上百万的工作场所，束缚了数十亿职场人的潜力。超时工作、过大的工作量、缺乏睡眠，这些已经成了现代人的“荣誉徽章”。可作者认为这其实是愚蠢的标志。悲哀的是，这不仅是大公司才会遇到的问题，个人、承包商、个体企业家也都在用相同的方式损耗着自己。提高生产力的办法不是投入更多时间，而是减少浪费，减少那些带来干扰和持续压力的事。别再颂扬“疯狂”了，现在是倡导“冷静”的时候了！在这个问题上，作者拿出了坚实的论据。自从20年前创立Basecamp起，两位作者就把“冷静”设为公司文化的基石。本书汇集了他们的洞见与真实经验，既实用又有启发性，必将成为管理者的新一代管理指南。这并不是一本告诉你“应该做什么”的书，本书告诉你的是“他们已经做了什么”，而且会让你看到，每一位管理者和经理人——无论身处什么行业，公司规模是大还是小——都能做到这些。")],-1))])]),e[9]||(e[9]=t('<h2 id="我们是谁" tabindex="-1" data-v-849ea9f1>我们是谁？ <a class="header-anchor" href="#我们是谁" aria-label="Permalink to “我们是谁？”" data-v-849ea9f1>​</a></h2><blockquote class="reading-excerpt" id="excerpt-001" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>001</span><div data-v-849ea9f1><p data-v-849ea9f1>把书中的想法当作寻求改变的灵感，而不是不能改动的金科玉律。</p></div></blockquote><h2 id="边走边摸索" tabindex="-1" data-v-849ea9f1>边走边摸索 <a class="header-anchor" href="#边走边摸索" aria-label="Permalink to “边走边摸索”" data-v-849ea9f1>​</a></h2><blockquote class="reading-excerpt" id="excerpt-002" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>002</span><div data-v-849ea9f1><p data-v-849ea9f1>长期计划会让人产生一种虚假的安全感</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-003" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>003</span><div data-v-849ea9f1><p data-v-849ea9f1>一样东西离你越远，就越是模糊。未来就是如此，而且它还充斥着上百万个你无法掌控的变数。关于决策，你能掌握的最佳信息是在执行的时候获得的。我们等待这样的时刻来做出明智的决定。</p></div></blockquote><h2 id="比别人更努力-就能出类拔萃" tabindex="-1" data-v-849ea9f1>比别人更努力，就能出类拔萃？ <a class="header-anchor" href="#比别人更努力-就能出类拔萃" aria-label="Permalink to “比别人更努力，就能出类拔萃？”" data-v-849ea9f1>​</a></h2><blockquote class="reading-excerpt" id="excerpt-004" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>004</span><div data-v-849ea9f1><p data-v-849ea9f1>更糟的是，管理层赞扬这样的员工，认为他们有良好的职业道德——因为他们始终待命，随叫随到，永远在工作。这是对职业道德的严重曲解，同时也是“工作过度”的典型案例。良好的职业道德指的不是随叫随到，而是说到做到、踏踏实实地做好每一天的事。尊重工作，尊重顾客，尊重同事，不浪费时间，不给别人制造不必要的麻烦，不做“瓶颈”。职业道德指的是做一个本质上的好人：值得他人信赖，是令人愉快的工作伙伴。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-005" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>005</span><div data-v-849ea9f1><p data-v-849ea9f1>所以，把“比别人更努力”的念头从脑子里清除出去吧。别再把职业道德跟超长的工作时间画等号。</p></div></blockquote><h2 id="上班时反而没法完成工作-为什么" tabindex="-1" data-v-849ea9f1>上班时反而没法完成工作，为什么？ <a class="header-anchor" href="#上班时反而没法完成工作-为什么" aria-label="Permalink to “上班时反而没法完成工作，为什么？”" data-v-849ea9f1>​</a></h2><blockquote class="reading-excerpt" id="excerpt-006" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>006</span><div data-v-849ea9f1><p data-v-849ea9f1>工作中最大的干扰并非来自外界，而是来自内部：到处溜达，经常询问工作进度的管理人员；收效甚微，却又连带出下周另一个会议的会议；沙丁鱼罐头般拥挤的格子间；销售部响个不停的电话铃；楼下食堂喧闹的人声。这些都是与现代办公室相伴相随的、有毒的副作用。</p></div></blockquote><h2 id="低处的果子未必摘得到" tabindex="-1" data-v-849ea9f1>低处的果子未必摘得到 <a class="header-anchor" href="#低处的果子未必摘得到" aria-label="Permalink to “低处的果子未必摘得到”" data-v-849ea9f1>​</a></h2><blockquote class="reading-excerpt" id="excerpt-007" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>007</span><div data-v-849ea9f1><p data-v-849ea9f1>你认为自己马上就能干成一件事，多半是因为你之前从没尝试过</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-008" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>008</span><div data-v-849ea9f1><p data-v-849ea9f1>请尊重你从没做过的事。提醒自己，他人的工作没有那么简单。不花力气极少能获得成果。如果你有经验，也有行动力，那么困难的任务也有可能显得挺简单，可你绝对不要忘记，“之前没做过”并不会让一件事变得容易，相反，这往往会令事情变得更困难。</p></div></blockquote><h2 id="简历不重要" tabindex="-1" data-v-849ea9f1>简历不重要 <a class="header-anchor" href="#简历不重要" aria-label="Permalink to “简历不重要”" data-v-849ea9f1>​</a></h2><blockquote class="reading-excerpt" id="excerpt-009" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>009</span><div data-v-849ea9f1><p data-v-849ea9f1>把关注重点放在候选人的人品和工作能力上，免得聘用一个想象出来的虚像。人们很容易被精心编造出来的故事蒙骗。家世高贵，名校毕业，此前就职的公司大名一个个如雷贯耳，怎能不招人爱呢？公司就这样雇到了错误的人，因为他们根据之前的成绩做出判断，而不是当下的能力。</p></div></blockquote><h2 id="不做薪酬谈判" tabindex="-1" data-v-849ea9f1>不做薪酬谈判 <a class="header-anchor" href="#不做薪酬谈判" aria-label="Permalink to “不做薪酬谈判”" data-v-849ea9f1>​</a></h2><blockquote class="reading-excerpt" id="excerpt-010" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>010</span><div data-v-849ea9f1><p data-v-849ea9f1>无论你选择住在哪里，我们一律支付相同的、居于市场领先水平的薪资。毕竟你住在哪里跟你的工作质量没半点关系，而我们付钱买的是你的工作质量</p></div></blockquote><h2 id="拒绝假-度假" tabindex="-1" data-v-849ea9f1>拒绝假“度假” <a class="header-anchor" href="#拒绝假-度假" aria-label="Permalink to “拒绝假“度假””" data-v-849ea9f1>​</a></h2><blockquote class="reading-excerpt" id="excerpt-011" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>011</span><div data-v-849ea9f1><p data-v-849ea9f1>模糊会滋生焦虑</p></div></blockquote><h2 id="新常态" tabindex="-1" data-v-849ea9f1>新常态 <a class="header-anchor" href="#新常态" aria-label="Permalink to “新常态”" data-v-849ea9f1>​</a></h2><blockquote class="reading-excerpt" id="excerpt-012" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>012</span><div data-v-849ea9f1><p data-v-849ea9f1>文化即行为。你有怎样的期待或希望都不算数，它就是你的行为举止，是你日常做的每一件事。所以，做得好点。</p></div></blockquote><h2 id="最糟实践" tabindex="-1" data-v-849ea9f1>最糟实践 <a class="header-anchor" href="#最糟实践" aria-label="Permalink to “最糟实践”" data-v-849ea9f1>​</a></h2><blockquote class="reading-excerpt" id="excerpt-013" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>013</span><div data-v-849ea9f1><p data-v-849ea9f1>遵循任何一条最佳实践之前，都该提醒自己要认真思考。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-014" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>014</span><div data-v-849ea9f1><p data-v-849ea9f1>找到最适合自己的方法，做下去就行了。创造属于自己的经验和行为模式，至于这些做法对别人来说算不算最佳实践？管它呢。</p></div></blockquote><h2 id="不惜任何代价" tabindex="-1" data-v-849ea9f1>不惜任何代价？ <a class="header-anchor" href="#不惜任何代价" aria-label="Permalink to “不惜任何代价？”" data-v-849ea9f1>​</a></h2><blockquote class="reading-excerpt" id="excerpt-015" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>015</span><div data-v-849ea9f1><p data-v-849ea9f1>提问会带来解决方案，而命令只会毁掉它们。</p></div></blockquote><h2 id="多一事不如少一事" tabindex="-1" data-v-849ea9f1>多一事不如少一事 <a class="header-anchor" href="#多一事不如少一事" aria-label="Permalink to “多一事不如少一事”" data-v-849ea9f1>​</a></h2><blockquote class="reading-excerpt" id="excerpt-016" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>016</span><div data-v-849ea9f1><p data-v-849ea9f1>时间不是你能管理的东西。时间就是时间——无论你试图用怎样的方式和它搏斗，它始终以相同的速度往前流去。你唯一能掌控的，就是把时间花在哪里。</p></div></blockquote><h2 id="季节轮转" tabindex="-1" data-v-849ea9f1>季节轮转 <a class="header-anchor" href="#季节轮转" aria-label="Permalink to “季节轮转”" data-v-849ea9f1>​</a></h2><blockquote class="reading-excerpt" id="excerpt-017" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>017</span><div data-v-849ea9f1><p data-v-849ea9f1>人们总认为改变会带来压力，但它的反面——也就是一成不变，给人的感觉更糟。你用相同的方式、相同的步调，做着相同的事情，时间一长，单调的感觉就会反噬。</p></div></blockquote><h2 id="别做承诺" tabindex="-1" data-v-849ea9f1>别做承诺 <a class="header-anchor" href="#别做承诺" aria-label="Permalink to “别做承诺”" data-v-849ea9f1>​</a></h2><blockquote class="reading-excerpt" id="excerpt-018" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>018</span><div data-v-849ea9f1><p data-v-849ea9f1>承诺说起来容易，好似也不需要代价，而真正的工作既艰难又昂贵。如果不是这样的话，你不是会立即做完吗？而不是答应人家“以后做”。</p></div></blockquote><h2 id="他抄我的" tabindex="-1" data-v-849ea9f1>他抄我的！ <a class="header-anchor" href="#他抄我的" aria-label="Permalink to “他抄我的！”" data-v-849ea9f1>​</a></h2><blockquote class="reading-excerpt" id="excerpt-019" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>019</span><div data-v-849ea9f1><p data-v-849ea9f1>当有人抄袭时，他们抄到的只是那一刻的成果。他们不知道那个成果背后的思路，而且他们也不会知道能帮你日后做出无数新成果的思路。他们被困在你的过往里了。所以呀，说真的，冷静下来。接纳那一阵微弱的、暂时的挫折感，然后放手让它走。</p></div></blockquote><h2 id="掌控变化" tabindex="-1" data-v-849ea9f1>掌控变化 <a class="header-anchor" href="#掌控变化" aria-label="Permalink to “掌控变化”" data-v-849ea9f1>​</a></h2><blockquote class="reading-excerpt" id="excerpt-020" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>020</span><div data-v-849ea9f1><p data-v-849ea9f1>你常听到有人说，人们不喜欢变化。但这话不一定对。对于想要的变化，人们接受起来一点儿问题都没有。他们不喜欢的是被迫改变——在一个并非由他们主动选择的时间点上，发生了他们并未主动要求的改变。</p></div></blockquote><h2 id="小事一桩-还是世界末日" tabindex="-1" data-v-849ea9f1>小事一桩，还是世界末日？ <a class="header-anchor" href="#小事一桩-还是世界末日" aria-label="Permalink to “小事一桩，还是世界末日？”" data-v-849ea9f1>​</a></h2><blockquote class="reading-excerpt" id="excerpt-021" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>021</span><div data-v-849ea9f1><p data-v-849ea9f1>人人都希望得到尊重和倾听，而且这样做的成本通常并不高，谁对谁错并没有那么重要。带着情绪争执这种问题，只会加剧矛盾。</p></div></blockquote><h2 id="美好的旧时光" tabindex="-1" data-v-849ea9f1>美好的旧时光 <a class="header-anchor" href="#美好的旧时光" aria-label="Permalink to “美好的旧时光”" data-v-849ea9f1>​</a></h2><blockquote class="reading-excerpt" id="excerpt-022" data-v-849ea9f1><span class="reading-excerpt-number" aria-hidden="true" data-v-849ea9f1>022</span><div data-v-849ea9f1><p data-v-849ea9f1>无论压力多大，世上并没有哪条自然法则规定，企业必须快速且永无止境地增长。只有那么几句商业金句式的蠢话，说什么“如果停止增长，就意味着死亡。”谁说的？</p></div></blockquote><footer class="reading-footer" data-v-849ea9f1><span data-v-849ea9f1>书籍来源：微信读书</span><span data-v-849ea9f1>整理时间：2025年</span></footer>',41))])])}const _=r(v,[["render",h],["__scopeId","data-v-849ea9f1"]]);export{q as __pageData,_ as default};
